window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-22c361b75c7d4bce"]={"versions": [{"id": "FIG-22c361b75c7d4bce", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Statisches Schichten- und Komponentenarchitekturdiagramm (AUTOSAR Adaptive Platform Stack Architecture).</li>\n<li><strong>Architektur-Kontext:</strong> Verortung des <strong>System Health Monitors (SHM)</strong> gemäß <code>AUTOSAR_EXP_SystemHealthMonitoring</code> (R20-11). Das Diagramm definiert die funktionale Abgrenzung: Der SHM ist <strong>kein</strong> plattforminterner Functional Cluster (FC) der <em>AUTOSAR Runtime for Adaptive Applications (ARA)</em>, sondern architektonisch als eigenständige <strong>User Application</strong> im Anwendungsraum angesiedelt. Er fungiert als übergeordnete Instanz zur Überwachung, Aggregation und Koordination von Systemzuständen über die standardisierten ARA-Schnittstellen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichtenstruktur (Top-Down)</p>\n<ol class=\"fig-list\">\n<li><strong>User Applications (Anwendungsebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong><code>SHM</code> (System Health Monitor):</strong> Blau hervorgehoben; standardisierter POSIX-Prozess im User Space.</li>\n<li><strong><code>Adaptive Application</code>:</strong> Reguläre Anwendungs-SWCs (Prozesse).</li>\n<li><strong><code>ASW::XYZ Non-PF Service</code> / <code>ASW::ABC Non-PF Service</code>:</strong> Anwendungsdienste, die Funktionalitäten bereitstellen, jedoch nicht zur Platform Foundation gehören (Stereotyp: <code>SERVICE Non-PF Service</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Platform Foundation Functional Clusters (Kompilierte C++-Bibliotheken / Direkt-APIs):</strong></li>\n<li><code>ara::core</code>: Basistypen, Fehlerbehandlung (<code>Result</code>, <code>ErrorCode</code>), Pointer- und Speicherabstraktionen.</li>\n<li><code>ara::com</code>: Serviceorientierte Kommunikation mit Bindings für <code>SOME/IP</code>, <code>IPC (local)</code> und <code>DDS</code>.</li>\n<li><code>ara::rest</code>: RESTful-Schnittstellenabstraktion.</li>\n<li><code>ara::tsync</code>: Zeitsynchronisation (z. B. IEEE 802.1AS / PTP).</li>\n<li><code>ara::per</code>: Persistenz (Flash/NVRAM-Zugriff).</li>\n<li><code>ara::phm</code> (Platform Health Management): Lokale Überwachung (Alive-, Deadline-, Logical Supervision sowie Health Channels).</li>\n<li><code>ara::exec</code>: Execution Management (Prozessstart, Determinismus, Function Group States).</li>\n<li><code>ara::iam</code>: Identity and Access Management (Zugriffskontrolle und Privilegien).</li>\n<li><code>ara::log</code>: Logging- und Tracing-Framework.</li>\n<li><code>ara::crypto</code>: Kryptografische Dienste (Schlüsselverwaltung, Signatur-/Verschlüsselungsoperationen).</li>\n<li><code>POSIX PSE51 / C++ STL Operating System Interface</code>: Betriebssystemabstraktion (POSIX-Profil PSE51 für Single-Process-Multithreaded bzw. Multiprocess POSIX Subsets).</li>\n<li><strong>Platform Service Functional Clusters (Dienste über <code>ara::com</code> / Service-Daemon-Architektur):</strong></li>\n<li><code>ara::sm service</code>: State Management (Koordination von System- und Funktionsgruppenzuständen).</li>\n<li><code>ara::diag service</code>: Diagnose-Server (DoIP / UDS-Kommunikation).</li>\n<li><code>ara::s2s service</code>: Signal-to-Service Mapping (Transformation klassischer Bus-Signale in Services).</li>\n<li><code>ara::nm service</code>: Network Management (Bus-Sleep, Wakeup).</li>\n<li><code>ara::ucm service</code>: Update and Config Management (Software-Updates / FOTA).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Infrastruktur-Schicht:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>(Virtual) Machine / Container / Hardware</code>: OS-Kernel, Virtualisierungs-/Hypervisor-Layer oder bare-metal HW.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert die statische Schichtung; daraus leiten sich folgende operative Interaktionsketten für den SHM ab:</p>\n<ol class=\"fig-list\">\n<li><strong>Lokale Fehlererfassung (<code>ara::phm</code> $\\rightarrow$ <code>SHM</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Lokale Adaptive Applications reporten Checkpoints an <code>ara::phm</code>.</li>\n<li>Bei Überschreitung von Deadlines oder Alive-Raten löst <code>ara::phm</code> lokale Recovery Actions aus und propagiert den Gesundheitsstatus an den <code>SHM</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Systemweite Zustandskontrolle (<code>SHM</code> $\\rightarrow$ <code>ara::sm</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der SHM bewertet systemische Fehlzustände (Multi-Core, Multi-Partition oder ECU-übergreifend) und triggert über <code>ara::com</code> Zustandswechsel in <code>ara::sm</code>, um Function Groups in Safe States, Degraded Modes oder Neustarts zu überführen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Plattformübergreifende Diagnose & Reporting (<code>SHM</code> $\\leftrightarrow$ <code>ara::diag</code> / <code>ara::com</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der SHM persistiert Fehlereinträge über <code>ara::diag</code> im Diagnosespeicher (DTC-Reporting).</li>\n<li>Über <code>ara::com</code> (SOME/IP oder DDS) synchronisiert sich der SHM maschinenübergreifend mit System Health Monitoring-Instanzen der AUTOSAR Classic Platform oder Cloud-/Edge-Aggregatoren.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Keine Plattform-Privilegien für SHM:</strong> Da der SHM als User Application implementiert ist, operiert er vollständig innerhalb der Sandbox-Beschränkungen von <code>POSIX PSE51</code> und unterliegt der Autorisierungsprüfung durch <code>ara::iam</code>. Er besitzt keinen privilegierten Kernel- oder Hardware-Direktzugriff.</li>\n<li><strong>Rollentrennung <code>ara::phm</code> vs. <code>SHM</code>:</strong></li>\n<li><code>ara::phm</code> ist zuständig für <strong>lokale, deterministische Echtzeitüberwachung</strong> einzelner Prozesse auf derselben Machine/OS-Instanz.</li>\n<li>Der <code>SHM</code> realisiert die <strong>systemweite, strategische Health-Ebene</strong> (Korrelation plattformweiter Fehler, Koordination über Maschinen- und OS-Grenzen hinweg).</li>\n<li><strong>API-Verträge & Abhängigkeiten:</strong> Entwickler eines SHM-Dienstes müssen sicherstellen, dass die Prozessabhängigkeiten in <code>ara::exec</code> (Manifest / Execution State Manifest) korrekt konfiguriert sind, sodass der SHM nach den Basis-Services (<code>ara::com</code>, <code>ara::sm</code>, <code>ara::phm</code>) hochfährt.</li>\n<li><strong>Service-Deployment:</strong> Kommunikationsbeziehungen zwischen SHM und Applikationen bzw. Platform Services müssen vollständig im AUTOSAR ARXML-Modell als Service-Interfaces (<code>ProvidedServiceInstance</code>, <code>RequiredServiceInstance</code>) deklariert sein.</li>\n</ul>"}, {"id": "FIG-566cc16cde306baf", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Statisches Schichten- und Komponentenarchitekturdiagramm (AUTOSAR Adaptive Platform Stack Architecture).</li>\n<li><strong>Architektur-Kontext:</strong> Verortung des <strong>System Health Monitors (SHM)</strong> gemäß <code>AUTOSAR_EXP_SystemHealthMonitoring</code> (R20-11). Das Diagramm definiert die funktionale Abgrenzung: Der SHM ist <strong>kein</strong> plattforminterner Functional Cluster (FC) der <em>AUTOSAR Runtime for Adaptive Applications (ARA)</em>, sondern architektonisch als eigenständige <strong>User Application</strong> im Anwendungsraum angesiedelt. Er fungiert als übergeordnete Instanz zur Überwachung, Aggregation und Koordination von Systemzuständen über die standardisierten ARA-Schnittstellen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichtenstruktur (Top-Down)</p>\n<ol class=\"fig-list\">\n<li><strong>User Applications (Anwendungsebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong><code>SHM</code> (System Health Monitor):</strong> Blau hervorgehobene User Application im User Space.</li>\n<li><strong><code>Adaptive Application</code>:</strong> Zwei reguläre Instanzen von Adaptive Applications (orange hinterlegt).</li>\n<li><strong><code>ASW::XYZ Non-PF Service</code> / <code>ASW::ABC Non-PF Service</code>:</strong> Anwendungsdienste (orange hinterlegt, Stereotyp: <code>SERVICE Non-PF Service</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Platform Foundation Functional Clusters (Kompilierte C++-Bibliotheken / Direkt-APIs mit blauer Kopfleiste, <code>API Platform Foundation FCs</code>):</strong></li>\n<li><code>ara::core</code>: Core.</li>\n<li><code>ara::com</code>: Serviceorientierte Kommunikation mit Bindings für <code>IPC</code>, <code>Signal PDU</code>, <code>SOME/IP</code> und <code>DDS</code>.</li>\n<li><code>ara::idsm</code>: Intrusion Detection System Manager.</li>\n<li><code>ara::tsync</code>: Time Synchronization.</li>\n<li><code>ara::diag</code>: Diagnostics.</li>\n<li><code>ara::per</code>: Persistency.</li>\n<li><code>ara::phm</code>: Platform Health Management.</li>\n<li><code>ara::log</code>: Log and Trace.</li>\n<li><code>ara::exec</code>: Execution Management.</li>\n<li><code>ara::iam</code>: Identity and Access Management.</li>\n<li><code>ara::crypto</code>: Cryptography.</li>\n<li><code>POSIX PSE51 / C++ STL Operating System Interface</code>: Betriebssystemabstraktion.</li>\n<li><strong>Platform Service Functional Clusters (Dienste über <code>ara::com</code> mit grauer Kopfleiste, <code>SERVICE Platform Service FCs</code>):</strong></li>\n<li><code>ara::sm service</code>: State Management.</li>\n<li><code>ara::ucm service</code>: Update and Config Management.</li>\n<li><code>ara::nm service</code>: Network Management.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Infrastruktur-Schicht:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>(Virtual) Machine / Container / Hardware</code>: Betriebssystemkernel, Virtualisierung/Container oder Hardware.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Überwachung lokaler Applikationen (<code>ara::phm</code> / <code>SHM</code>):</strong> Adaptive Applications und Non-PF Services reporten Supervisionsdaten an <code>ara::phm</code>. <code>ara::phm</code> meldet aggregierte Gesundheitszustände an den <code>SHM</code>.</li>\n<li><strong>Security- und Integritätsüberwachung (<code>ara::idsm</code> / <code>SHM</code>):</strong> Sicherheitsrelevante Ereignisse und Angriffsindikatoren werden durch <code>ara::idsm</code> erfasst und stehen dem System Health Monitoring zur ganzheitlichen Systembewertung zur Verfügung.</li>\n<li><strong>Zustands- und Fehlerreaktion (<code>SHM</code> $\\rightarrow$ <code>ara::sm service</code>):</strong> Der <code>SHM</code> verarbeitet Gesundheits- und Integritätszustände und triggert bei Ausfällen über <code>ara::sm service</code> definierte Wiederanlauf- oder Degradierungsstrategien.</li>\n<li><strong>Kommunikationsbeziehungen:</strong> Plattform-Dienste (<code>ara::sm</code>, <code>ara::ucm</code>, <code>ara::nm</code>) sowie Non-PF Services werden über <code>ara::com</code> angebunden. Dabei stehen neben <code>IPC</code>, <code>SOME/IP</code> und <code>DDS</code> auch direkte <code>Signal PDU</code>-Bindings zur Verfügung. Die Diagnose (<code>ara::diag</code>) sowie <code>ara::idsm</code> sind als Platform Foundation APIs direkt im Prozesskontext eingebunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifizierung von <code>ara::diag</code>:</strong> Die Diagnosefunktionalität ist als <code>Platform Foundation FC</code> mit direkter C++-API realisiert, nicht mehr als <code>Platform Service FC</code>.</li>\n<li><strong>Security-Integration:</strong> Mit <code>ara::idsm</code> ist das Intrusion Detection System als nativer Platform Foundation Functional Cluster bindend in die Plattform-Architektur integriert.</li>\n<li><strong>Signalkommunikation:</strong> Signalbasierte Kommunikation wird über das Kommunikationsbinding <code>Signal PDU</code> direkt in <code>ara::com</code> abgebildet; ein separater Service-Cluster <code>ara::s2s</code> existiert nicht.</li>\n<li><strong>Architekturvorgabe:</strong> Der <code>SHM</code> agiert als reguläre User Application unter ausschließlicher Nutzung der ARA-Schnittstellen und des OS-Interfaces (POSIX PSE51 / C++ STL).</li>\n</ul>"}, {"id": "FIG-11ca8343c8af7024", "releases": ["R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Statisches Schichten- und Komponentenarchitekturdiagramm (AUTOSAR Adaptive Platform Stack Architecture).</li>\n<li><strong>Architektur-Kontext:</strong> Verortung des <strong>System Health Monitors (SHM)</strong> gemäß <code>AUTOSAR_EXP_SystemHealthMonitoring</code> (R20-11). Das Diagramm definiert die funktionale Abgrenzung: Der SHM ist <strong>kein</strong> plattforminterner Functional Cluster (FC) der <em>AUTOSAR Runtime for Adaptive Applications (ARA)</em>, sondern architektonisch als eigenständige <strong>User Application</strong> im Anwendungsraum angesiedelt. Er fungiert als übergeordnete Instanz zur Überwachung, Aggregation und Koordination von Systemzuständen über die standardisierten ARA-Schnittstellen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichtenstruktur (Top-Down)</p>\n<ol class=\"fig-list\">\n<li><strong>User Applications (Anwendungsebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong><code>SHM</code> (System Health Monitor):</strong> Blau hervorgehobene User Application im User Space.</li>\n<li><strong><code>Adaptive Application</code>:</strong> Zwei reguläre Instanzen von Adaptive Applications (orange hinterlegt).</li>\n<li><strong><code>ASW::XYZ Non-PF Service</code> / <code>ASW::ABC Non-PF Service</code>:</strong> Anwendungsdienste (orange hinterlegt, Stereotyp: <code>SERVICE Non-PF Service</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Platform Foundation Functional Clusters (Kompilierte C++-Bibliotheken / Direkt-APIs mit blauer Kopfleiste, <code>API Platform Foundation FCs</code>):</strong></li>\n<li><code>ara::core</code>: Core.</li>\n<li><code>ara::com</code>: Serviceorientierte Kommunikation mit Bindings für <code>IPC</code>, <code>Signal PDU</code>, <code>SOME/IP</code> und <code>DDS</code>.</li>\n<li><code>ara::idsm</code>: Intrusion Detection System Manager.</li>\n<li><code>ara::tsync</code>: Time Synchronization.</li>\n<li><code>ara::diag</code>: Diagnostics.</li>\n<li><code>ara::per</code>: Persistency.</li>\n<li><code>ara::phm</code>: Platform Health Management.</li>\n<li><code>ara::log</code>: Log and Trace.</li>\n<li><code>ara::exec</code>: Execution Management.</li>\n<li><code>ara::iam</code>: Identity and Access Management.</li>\n<li><code>ara::crypto</code>: Cryptography.</li>\n<li><code>ara::fw</code>: Firewall (netzwerk- und sicherheitsbezogene Paketfilterung / Schnittstellenschutz).</li>\n<li><code>POSIX PSE51 / C++ STL Operating System Interface</code>: Betriebssystemabstraktion.</li>\n<li><strong>Platform Service Functional Clusters (Dienste über <code>ara::com</code> mit grauer Kopfleiste, <code>SERVICE Platform Service FCs</code>):</strong></li>\n<li><code>ara::sm service</code>: State Management.</li>\n<li><code>ara::ucm service</code>: Update and Config Management.</li>\n<li><code>ara::nm service</code>: Network Management.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Infrastruktur-Schicht:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>(Virtual) Machine / Container / Hardware</code>: Betriebssystemkernel, Virtualisierung/Container oder Hardware.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Überwachung lokaler Applikationen (<code>ara::phm</code> / <code>SHM</code>):</strong> Adaptive Applications und Non-PF Services reporten Supervisionsdaten an <code>ara::phm</code>. <code>ara::phm</code> meldet aggregierte Gesundheitszustände an den <code>SHM</code>.</li>\n<li><strong>Security- und Integritätsüberwachung (<code>ara::idsm</code> / <code>SHM</code>):</strong> Sicherheitsrelevante Ereignisse und Angriffsindikatoren werden durch <code>ara::idsm</code> erfasst und stehen dem System Health Monitoring zur ganzheitlichen Systembewertung zur Verfügung.</li>\n<li><strong>Zustands- und Fehlerreaktion (<code>SHM</code> $\\rightarrow$ <code>ara::sm service</code>):</strong> Der <code>SHM</code> verarbeitet Gesundheits- und Integritätszustände und triggert bei Ausfällen über <code>ara::sm service</code> definierte Wiederanlauf- oder Degradierungsstrategien.</li>\n<li><strong>Kommunikationsbeziehungen:</strong> Plattform-Dienste (<code>ara::sm</code>, <code>ara::ucm</code>, <code>ara::nm</code>) sowie Non-PF Services werden über <code>ara::com</code> angebunden. Dabei stehen neben <code>IPC</code>, <code>SOME/IP</code> und <code>DDS</code> auch direkte <code>Signal PDU</code>-Bindings zur Verfügung. Die Diagnose (<code>ara::diag</code>) sowie <code>ara::idsm</code> sind als Platform Foundation APIs direkt im Prozesskontext eingebunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Firewall-Cluster <code>ara::fw</code>:</strong> Mit <code>ara::fw</code> ist ein dedizierter Functional Cluster für Firewall-Funktionalität als Platform Foundation FC (C++ Direct-API) spezifiziert.</li>\n<li><strong>Sicherheitsarchitektur:</strong> Die Plattform kombiniert die Erkennung von Sicherheitsvorfällen (<code>ara::idsm</code>), Kryptografie (<code>ara::crypto</code>), Zugriffskontrolle (<code>ara::iam</code>) und aktive Filterung (<code>ara::fw</code>) auf Ebene der Platform Foundation.</li>\n<li><strong>Architekturvorgabe:</strong> Der <code>SHM</code> bleibt als unprivilegierte User Application strikt von den internen Functional Clustern der ARA getrennt.</li>\n</ul>"}], "trans": [{"from": "FIG-22c361b75c7d4bce", "to": "FIG-566cc16cde306baf", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Neue Komponente <code>ara::idsm</code> (Intrusion Detection System Manager) als Platform Foundation FC hinzugefügt; <code>ara::rest</code> entfällt.</li>\n<li><code>ara::diag</code> von Platform Service FC (<code>ara::diag service</code>) zu Platform Foundation FC (C++ Direct-API mit blauer Kopfleiste) umklassifiziert.</li>\n<li><code>ara::s2s service</code> (Signal to Service Mapping) als Platform Service FC entfällt; stattdessen ist <code>Signal PDU</code> als neues Transport-/Protokoll-Binding unter <code>ara::com</code> integriert.</li>\n<li><code>ara::core Core Types</code> zu <code>ara::core Core</code> umbenannt.</li>\n<li>Eine der drei generischen <code>Adaptive Application</code>-Instanzen entfällt (zwei statt zuvor drei Instanzen dargestellt).</li>\n<li>Farbcodierung im Block <code>User Applications</code> und in der Legende (<code>Key</code>) angepasst: Anwendungsdienste und Anwendungen sind orange hinterlegt.</li>\n</ul>"}, {"from": "FIG-566cc16cde306baf", "to": "FIG-11ca8343c8af7024", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Neuer Functional Cluster <code>ara::fw</code> (Firewall) als Platform Foundation FC (blaue Kopfleiste) in der untersten FC-Reihe neben <code>POSIX PSE51 / C++ STL Operating System Interface</code> ergänzt.</li>\n</ul>"}]};
